function fixture(mode='fast',windows=[100]){let now=0,monitor,buffered=0;const pending=[];const video={currentTime:0,paused:false,seeking:false,hidden:false,plays:0,play(){this.plays++;return Promise.resolve();}},els={video,'waiting':{},'waiting-text':{},'status':{},'network-mode':{value:mode},'playback-mode':{value:'balanced'}};class Hls{static isSupported(){return true;}static Events={MANIFEST_PARSED:'manifest',LEVEL_LOADED:'level',FRAG_BUFFERED:'frag',ERROR:'error'};static ErrorTypes={MEDIA_ERROR:'media'};constructor(c){this.config=c;this.events={};this.loads=0;this.starts=0;}on(e,fn){this.events[e]=fn;}loadSource(){this.loads++;}attachMedia(){}startLoad(){this.starts++;}recoverMediaError(){}}const ctx={fetch:async()=>({ok:true,text:async()=>'#EXTM3U\n#EXTINF:'+(windows.length>1?windows.shift():windows[0])+',\nsegment.ts'}),AbortSignal,state:{authorized:true,ready:true,stopped:false,selection:{kind:'url'}},generation:0,recoveryTimer:null,paused:false,running:false,hls:null,window:{Hls},Hls,$:id=>els[id],stopLocal(){ctx.generation++;},notice(){},playbackURL:()=>'/quality/auto.m3u8',buffer:()=>buffered,setInterval:fn=>{monitor=fn;return 1;},clearInterval(){},setTimeout:(fn,ms)=>{if(ms===1000)pending.push(fn);else fn();return 1;},clearTimeout(){},Date:{now:()=>now}};vm.createContext(ctx);vm.runInContext(source.slice(source.indexOf('function watch()'),source.indexOf('function buffer()'))+';watch();',ctx);return {ctx,video,els,pending,setBuffer:n=>{buffered=n;},tick:t=>{now=t;monitor();}};}
test('live player repairs a stalled moving stream and reloads its manifest without destroying media',()=>{const f=fixture(),p=f.ctx.hls;p.events.level(null,{details:{live:true}});f.tick(2000);p.liveSyncPosition=10;f.tick(10000);assert.equal(f.video.currentTime,10);assert.equal(p.starts,1);f.tick(12000);f.tick(20000);f.tick(28000);assert.equal(p.loads,2);assert.equal(f.ctx.generation,1);assert.equal(p.config.lowLatencyMode,false);});
test('manual pause, VOD, stopped broadcast and obsolete player never trigger live repair',()=>{for(const mode of ['pause','vod','stop','obsolete']){const f=fixture(),p=f.ctx.hls;p.events.level(null,{details:{live:mode!=='vod'}});f.tick(2000);if(mode==='pause')f.video.paused=true;if(mode==='stop')f.ctx.state.stopped=true;if(mode==='obsolete')f.ctx.generation++;f.tick(12000);f.tick(24000);assert.equal(p.starts,0,mode);assert.equal(p.loads,1,mode);}});

